:root {
  --ink: #26354a;
  --paper: #fffdf7;
  --line: #d9e1eb;
  --blue: #4d72c9;
  --blue-soft: #eaf0ff;
}

* {
  box-sizing: border-box;
}

.fold-card {
  width: 440px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.fold-mark {
  display: grid;
  width: 52px;
  height: 52px;
  place-items: center;
  background: var(--blue-soft);
  border-radius: 12px;
  font-size: 25px;
}

.fold-content {
  flex: 1;
}

.fold-content h1 {
  margin: 0 0 3px;
  color: var(--ink);
  font-size: 17px;
  line-height: 1.2;
}

.fold-content p {
  margin: 0;
  color: var(--ink);
  font-size: 13px;
  line-height: 1.35;
}

.fold-card footer {
  display: flex;
  align-items: flex-end;
  flex-direction: column;
  gap: 6px;
}

.status {
  color: var(--blue);
  font-size: 11px;
  font-weight: 700;
}

button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--blue);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}
